INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'metrorail-monthly-ticket-increase-from-1-december-2026-11-19',
  'Metrorail monthly tickets go up from 1 December, other fares unchanged for now',
  'Traffic', '2026-11-19', 'GroundUp', 'https://groundup.org.za/article/prasa-agrees-to-reduced-phased-increases/',
  'PRASA will raise monthly Metrorail tickets by R35 to R46 from 1 December, while single and weekly fares stay as they are for now.',
  'PRASA has confirmed that Metrorail monthly tickets will cost more from 1 December 2026. The rise is smaller than the agency first proposed, which was R60 to R80 per monthly ticket.

The new monthly prices depend on distance. Commuters in the shortest band, up to 15km, will pay R215 instead of R180. The 16km to 40km band becomes R266 (previously R220), and the 41km to 60km band becomes R291 (previously R250). The longest band, over 60km, becomes R322 from the current R280.

Single and weekly tickets are not affected at this stage. According to GroundUp, those fares were last raised in August 2025.

A second increase is planned for no earlier than 1 April 2027, with the exact date still to be confirmed. It will be linked to inflation and will cover all ticket types. After that, PRASA intends to adjust fares each year by roughly 4% to 4.5%.

GroundUp reports that PRASA reduced and phased the increase after talks with commuter group United Commuters Voice and the Department of Transport on 16 October. The agency intends to put the additional income into electricity costs, upkeep of trains and rail infrastructure, and security. Commuters who buy monthly tickets should expect the higher prices at the start of next month.',
  NULL, NULL, NULL,
  '["https://groundup.org.za/article/prasa-agrees-to-reduced-phased-increases/", "https://www.capetownetc.com/news/prasa-metrorail-fare-increases-december/"]',
  'agent'
);
INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'water-shutdowns-planned-23-to-26-november-2026-11-20',
  'Planned water shutdowns across Cape Town from 23 to 26 November',
  'Utilities', '2026-11-20', 'City of Cape Town', 'https://www.capetown.gov.za/media-and-news/planned-water-supply-maintenance-from-23-to-29-november-2026/',
  'The City will cut or reduce water in Woodstock, Claremont, Wetton, Schaapkraal, Brackenfell and other areas between 23 and 26 November for pipe work and tests.',
  'The City of Cape Town has published its planned water maintenance for the week from 23 November, with several full shutdowns.

On Tuesday 24 November, parts of Woodstock (Victoria, Pine, Salmon, Warwick, Queens, Woodlands and Ravenscraig roads) lose water from 09:00 to 18:00 while a bypass is installed. Hanover Park will have low pressure from 09:00 to 14:00. On Monday 23 November, Helderrand has a shutdown from 09:00 to 16:00, and supply may be intermittent.

On Wednesday 25 November, Canal Road in Wetton, between Plantation and Delos roads, is without water from 08:00 to 20:00. Dreyer Street and nearby roads in Claremont are off from 09:00 to 18:00, with tankers where required. Parts of Schaapkraal are off from 08:00 to 18:00, and an emergency repair on Papkuilsvlei Road in Philippi, running from 09:00 until midnight, may leave Schaapkraal without water at times and Strandfontein with low pressure.

The following day, Thursday 26 November, supply is switched off from 10:00 to 18:00 in sections of Brackenfell and Brackenfell South. These include Vredekloof, Arauna, Morgenster and Okavango Park.

Zero-pressure tests will also be done in Diep River, Atlantis, Montclair, Century City, Milnerton, Tamboerskloof, Gardens and other suburbs, so some homes may see low pressure or short outages.

The City advises residents to store enough water in clean, sealed containers beforehand and to keep taps closed when supply returns. Water may look milky for a short time and clears if left to stand. Updates and tanker locations are posted on @CityofCTAlerts on X.',
  NULL, NULL, NULL,
  '["https://www.capetown.gov.za/media-and-news/planned-water-supply-maintenance-from-23-to-29-november-2026/", "https://www.capetownetc.com/news/cape-town-water-disruptions-affected-areas-and-dates-in-november/"]',
  'agent'
);
INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'residents-asked-for-input-idp-2027-2032-2026-11-20',
  'Cape Town residents can comment on the 2027 to 2032 five-year plan until 20 January',
  'Community', '2026-11-20', 'City of Cape Town', 'https://www.capetown.gov.za/media-and-news/your-city-your-say-have-your-say-on-cape-towns-new-five-year-integrated-development-plan/',
  'The City opened public input on its 2027 to 2032 Integrated Development Plan on 20 November; submissions close on 20 January 2027.',
  'The City of Cape Town has opened public participation on its new Integrated Development Plan, known as the IDP, which covers 2027 to 2032. Input opened on 20 November 2026 and closes on 20 January 2027.

The IDP is the City''s main strategic plan for the new term of office that follows the local elections. It guides planning and development across the metro and underpins the annual budget, so priorities raised by residents can influence what gets funded.

Residents can respond in several ways. The quickest is the online survey at capetown.gov.za/IDPSurvey, which each person can complete only once. Input can also go through the City''s collaboration platform at capetown.govocal.com, by email to public.participation@capetown.gov.za, or as written submissions dropped at the nearest subcouncil office or library.

According to the City, its Public Participation unit will hold walkabouts in selected areas to help people complete the survey, and it can assist residents with a disability or who cannot read or write. For help, call 021 400 1450.',
  NULL, NULL, NULL,
  '["https://www.capetown.gov.za/media-and-news/your-city-your-say-have-your-say-on-cape-towns-new-five-year-integrated-development-plan/", "https://www.capetownetc.com/news/cape-town-idp-2027-2032-residents-invited-to-have-their-say/"]',
  'agent'
);
